import java.util.Arrays;

public class BooleanConverter {
    /**
     * Converts an array of object Booleans to primitives.
     * 
     * @param array  A Boolean array, may be null
     * @return A boolean array, null if null array input
     * @throws NullPointerException if array content is null
     */
    public static boolean[] toPrimitive(final Boolean[] array) {
        if (array == null) {
            return null;
        }

        boolean[] primitiveArray = new boolean[array.length];
        for (int i = 0; i < array.length; i++) {
            if (array[i] == null) {
                throw new NullPointerException("Array content is null");
            }
            primitiveArray[i] = array[i];
        }

        return primitiveArray;
    }

    public static void main(String[] args) {
        Boolean[] booleanArray = {true, false, true, null};
        try {
            boolean[] primitiveArray = toPrimitive(booleanArray);
            System.out.println(Arrays.toString(primitiveArray));
        } catch (NullPointerException e) {
            System.err.println(e.getMessage());
        }
    }
}

