import java.util.Arrays;

public class ArrayUtils {

    private static final Character[] EMPTY_ARRAY = new Character[0];

    /**
     * Defensive programming technique to change a <code>null</code> reference to an empty one.
     * This method returns an empty array for a <code>null</code> input array.
     * As a memory optimizing technique an empty array passed in will be overridden with the empty
     * <code>public static</code> references in this class.
     *
     * @param array  the array to check for <code>null</code> or empty
     * @return the same array, <code>public static</code> empty array if <code>null</code> or empty input
     * @since 2.5
     */
    public static Character[] nullToEmpty(final Character[] array) {
        if (array == null || array.length == 0) {
            return EMPTY_ARRAY;
        }
        return array;
    }

    public static void main(String[] args) {
        // Test cases
        Character[] testArray1 = null;
        Character[] testArray2 = new Character[0];
        Character[] testArray3 = new Character[]{1, 2, 3};

        System.out.println(Arrays.toString(nullToEmpty(testArray1))); // []
        System.out.println(Arrays.toString(nullToEmpty(testArray2))); // []
        System.out.println(Arrays.toString(nullToEmpty(testArray3))); // [1, 2, 3]
    }
}

