public class BeanMapExample {
    private BeanMap beanMap = new BeanMap();

    public void putAllWriteable(BeanMap map) {
        for (Object key : map.keySet()) {
            if (isWriteable(map, key)) {
                beanMap.put(key, map.get(key));
            }
        }
    }

    private boolean isWriteable(BeanMap map, Object key) {
        try {
            java.lang.reflect.Field field = map.getClass().getDeclaredField(key.toString());
            return !java.beans.PropertyDescriptor.propertyTypeIsReadOnly(field.getType());
        } catch (NoSuchFieldException e) {
            return false;
        }
    }

    public static void main(String[] args) {
        BeanMapExample example = new BeanMapExample();
        BeanMap map = new BeanMap();
        map.put(" writableProperty", "value");
        map.put("readOnlyProperty", "value");
        example.putAllWriteable(map);
        System.out.println(example.beanMap);
    }
}

