import java.io.IOException;
import java.io.InputStream;

public class BufferReader {
    private InputStream inputStream;
    private byte[] buffer;
    private int bufferIndex;
    private int bufferSize;

    public BufferReader(InputStream inputStream) {
        this.inputStream = inputStream;
        this.buffer = new byte[1024];
        this.bufferIndex = 0;
        this.bufferSize = 0;
    }

    public byte readByte() throws IOException {
        if (bufferIndex >= bufferSize) {
            refillBuffer();
        }
        return buffer[bufferIndex++];
    }

    private void refillBuffer() throws IOException {
        bufferSize = inputStream.read(buffer);
        bufferIndex = 0;
        if (bufferSize == -1) {
            throw new IOException("No more data available!");
        }
    }

    public static void main(String[] args) {
        try (InputStream inputStream = BufferReader.class.getResourceAsStream("/test.txt")) {
            BufferReader reader = new BufferReader(inputStream);
            while (true) {
                byte b = reader.readByte();
                System.out.print((char) b);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

