public class CaseInsensitiveCheck {
    /**
     * Case in-sensitive Checks if the String contains any character in the given set of string.
     *
     * @param str            the string to search
     * @param searchStrArray the list of strings to search for
     * @return true if the str contains any character in the searchStrArray, false otherwise
     */
    public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
        return searchStrArray.stream()
                .anyMatch(s -> str.toLowerCase().contains(s.toLowerCase()));
    }

    public static void main(String[] args) {
        System.out.println(containsAnyIgnoreCase("HelloWorld", Arrays.asList("world", "java"))); // true
        System.out.println(containsAnyIgnoreCase("HelloWorld", Arrays.asList("python", "java"))); // true
        System.out.println(containsAnyIgnoreCase("HelloWorld", Arrays.asList("go", "rust"))); // false
    }
}

