        if (head == node) {
            head = head.next;
            return true;
        }

        ListNodeImpl<E> current = head;
        while (current.next != null) {
            if (current.next == node) {
                current.next = current.next.next;
                return true;
            }
            current = current.next;
        }

        return false;
    }

