public class DoublyLinkedList<E> {
    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;
    private int size;

    private static class ListNodeImpl<E> {
        E data;
        ListNodeImpl<E> prev;
        ListNodeImpl<E> next;

        ListNodeImpl(E data) {
            this.data = data;
            this.prev = null;
            this.next = null;
        }
    }

    private void removeListNode(ListNodeImpl<E> node) {
        if (node == null) {
            throw new NullPointerException();
        }
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }
        size--;
    }

    private void addListNode(ListNodeImpl<E> node) {
        if (node == null) {
            throw new NullPointerException();
        }
        node.prev = tail;
        if (tail != null) {
            tail.next = node;
        } else {
            head = node;
        }
        tail = node;
        size++;
    }

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        ListNodeImpl<E> current = list.head;
        while (current != null) {
            ListNodeImpl<E> next = current.next;
            removeListNode(current);
            addListNode(current);
            current = next;
        }
    }

    public static void main(String[] args) {
        DoublyLinkedList<Integer> list1 = new DoublyLinkedList<>();
        list1.addListNode(new ListNodeImpl<>(1));
        list1.addListNode(new ListNodeImpl<>(2));
        list1.addListNode(new ListNodeImpl<>(3));

        DoublyLinkedList<Integer> list2 = new DoublyLinkedList<>();
        list2.moveAllListNodes(list1);

        System.out.println("List2 size: " + list2.size);
        ListNodeImpl<Integer> current = list2.head;
        while (current != null) {
            System.out.println(current.data);
            current = current.next;
        }
    }
}

