        for (int i = 0; i < numVertices; i++) {
            adjacencyList[i] = new HashSet<>();
        }
    }

    public void addEdge(V v1, V v2) {
        adjacencyList[(Integer) v1].add(v2);
        adjacencyList[(Integer) v2].add(v1);
    }

    private Set<V> initVisibleVertices() {
        Set<V> positiveDegreeVertices = new HashSet<>();
        for (int i = 0; i < adjacencyList.length; i++) {
            if (!adjacencyList[i].isEmpty()) {
                positiveDegreeVertices.add((V) i);
            }
        }
        return positiveDegreeVertices;
    }

    public static void main(String[] args) {
        GraphProcessor<Integer> graph = new GraphProcessor<>(5);
        graph.addEdge(0, 1);
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 4);

        Set<Integer> visibleVertices = graph.initVisibleVertices();
        System.out.println("Vertices with positive degree: " + visibleVertices);
    }
}

