        Set<Integer> set2 = new HashSet<>();
        set2.add(2);
        set2.add(3);
        set2.add(4);

        Set<Integer> intersection = new SetOperations().intersection(set1, set2);
        System.out.println(intersection); // Output: [2, 3]
    }
}

