import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;
import org.jgrapht.traverse.DepthFirstIterator;
import org.jgrapht.graph.DefaultListenableGraph;
import org.jgrapht.GraphPath;
import org.jgrapht.graph.AsUndirectedGraph;

import java.util.List;
import java.util.Set;
import java.util.HashSet;
import java.util.Stack;

public <V, E extends DefaultEdge> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<V> vertices = new ArrayList<>();
    for (E edge : tour) {
        vertices.add(edge.getSource());
        vertices.add(edge.getTarget());
    }
    vertices = new ArrayList<>(new HashSet<>(vertices));

    DefaultListenableGraph<V, E> subgraph = new SimpleListenableGraph<>(graph.getEdgeFactory());
    for (V vertex : vertices) {
        if (graph.containsVertex(vertex)) {
            subgraph.addVertex(vertex);
        }
    }
    for (E edge : tour) {
        if (graph.containsEdge(edge)) {
            subgraph.addEdge(edge.getSource(), edge.getTarget(), edge);
        }
    }

    DepthFirstIterator<V, E> iterator = new DepthFirstIterator<>(subgraph, vertices.get(0));
    List<V> pathVertices = new ArrayList<>();
    while (iterator.hasNext()) {
        pathVertices.add(iterator.next());
    }

    List<E> pathEdges = new ArrayList<>();
    for (int i = 0; i < pathVertices.size() - 1; i++) {
        E edge = graph.getEdge(pathVertices.get(i), pathVertices.get(i + 1));
        if (edge != null) {
            pathEdges.add(edge);
        }
    }

    return new AsUndirectedGraph<>(subgraph).createGraphPath(
        subgraph,
        pathVertices.get(0),
        pathVertices.get(pathVertices.size() - 1),
        pathEdges,
        0.0
    );
}

