import java.nio.ByteBuffer;

/**
 * Decodes octets to characters using the UTF-8 decoding and appends the characters to a StringBuffer.
 * @return the index to the next unchecked character in the string to decode
 */
private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b < 128) {
            sb.append((char) b);
        } else {
            int numBytes = 0;
            if ((b & 0xE0) == 0xC0) {
                numBytes = 1;
            } else if ((b & 0xF0) == 0xE0) {
                numBytes = 2;
            } else if ((b & 0xF8) == 0xF0) {
                numBytes = 3;
            } else {
                // Invalid UTF-8 byte
                return i + 1;
            }
            StringBuilder utf8Char = new StringBuilder();
            for (int j = 0; j < numBytes; j++) {
                int c = bb.get() & 0xFF;
                if ((c & 0xC0) != 0x80) {
                    // Invalid UTF-8 continuation byte
                    return i + 1;
                }
                utf8Char.append((char) c);
            }
            try {
                sb.append((char) Integer.parseInt(utf8Char.toString(), 2));
            } catch (NumberFormatException e) {
                return i + 1;
            }
        }
        i++;
    }
    return i;
}

