    private int index;

    public FileIterator(File directory) {
        if (directory.isDirectory()) {
            this.files = new ArrayList<>();
            File[] listFiles = directory.listFiles();
            if (listFiles != null) {
                for (File file : listFiles) {
                    if (file.isFile()) {
