                    }
                }
            }
            this.index = 0;
        } else {
            throw new IllegalArgumentException("Provided path is not a directory");
        }
    }

    public InputStream next() throws IOException {
        if (index < files.size()) {
            return new FileInputStream(files.get(index++));
        } else {
