import java.util.Properties;

public class VariableSubstitutor {
    public static String findAndSubst(String key, Properties props) {
        if (props.containsKey(key)) {
            String value = props.getProperty(key);
            return performSubstitution(value, props);
        }
        return null;
    }

    private static String performSubstitution(String value, Properties props) {
        while (value.contains("${")) {
            int startIndex = value.indexOf("${");
            int endIndex = value.indexOf("}", startIndex);
            if (endIndex == -1) {
                break;
            }
            String varName = value.substring(startIndex + 2, endIndex);
            if (props.containsKey(varName)) {
                value = value.substring(0, startIndex) + props.getProperty(varName) + value.substring(endIndex + 1);
            } else {
                break;
            }
        }
        return value;
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("key1", "value1");
        props.setProperty("key2", "${key1} and more");
        props.setProperty("key3", "${key2} and even more");
        System.out.println(findAndSubst("key3", props)); // Output: value1 and more and even more
    }
}

