public class FrameStackHandler {
    private Stack<String> outputFrameStack = new Stack<>();

    private void pop(final String descriptor) {
        int count = 0;
        if (descriptor.startsWith("(")) {
            // Descriptor is a method descriptor
            for (char c : descriptor.toCharArray()) {
                if (c == ')') {
                    break;
                }
                if (isObjectType(c)) {
                    count++;
                }
            }
        } else {
            // Descriptor is a type descriptor
            count = 1;
        }
        for (int i = 0; i < count; i++) {
            outputFrameStack.pop();
        }
    }

    private boolean isObjectType(char c) {
        // Simple heuristic to check if the character represents an object type
        return c == 'L';
    }

    public static void main(String[] args) {
        FrameStackHandler handler = new FrameStackHandler();
        handler.outputFrameStack.push("LObject;");
        handler.outputFrameStack.push("LInteger;");
        handler.outputFrameStack.push("LString;");

        handler.pop("(Ljava/lang/Object;)V");
        System.out.println("Remaining elements: " + handler.outputFrameStack);
    }
}

