import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;

public class LinkedBuffer {
    private final byte[] data;
    private int position;
    private final AtomicInteger refCount;

    private LinkedBuffer(byte[] data, int position, AtomicInteger refCount) {
        this.data = data;
        this.position = position;
        this.refCount = refCount;
    }

    public static LinkedBuffer create(int size) {
        byte[] data = new byte[size];
        AtomicInteger refCount = new AtomicInteger(1);
        return new LinkedBuffer(data, 0, refCount);
    }

    public int writeUTF8(CharSequence str) {
        byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);
        int bytesLength = bytes.length;

        if (position + bytesLength > data.length) {
            throw new IndexOutOfBoundsException("Buffer overflow");
        }

        System.arraycopy(bytes, 0, data, position, bytesLength);
        position += bytesLength;
        return bytesLength;
    }

    public byte[] toByteArray() {
        byte[] temp = new byte[position];
        System.arraycopy(data, 0, temp, 0, position);
        return temp;
    }
}

