import java.io.InputStream;

public class ProtocolBuffer {
    private InputStream inputStream;

    public ProtocolBuffer(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    public int readTag() throws IOException {
        int b = inputStream.read();
        if (b == -1) {
            return 0;
        }
        return ((b & 0x7f) << 3) | (b >>> 7);
    }

    public static void main(String[] args) {
        try (InputStream inputStream = new ByteArrayInputStream(new byte[]{0x08})) {
            ProtocolBuffer protocolBuffer = new ProtocolBuffer(inputStream);
            System.out.println(protocolBuffer.readTag()); // Output: 1
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

